// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address newOwner = address(0x1234);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        assertTrue(success && abi.decode(data, (bool)));
    }
}
